/* ================================================================
 * OLED_ShowChineseStr — display N consecutive Chinese characters
 * Line: 1-4, Column: 1-8 (each char = 16px = 2 ASCII columns)
 * ================================================================ */
void OLED_ShowChineseStr(uint8_t Line, uint8_t Column, const uint8_t **Fonts, uint8_t Count)
{
    uint8_t i;
    for (i = 0; i < Count; i++)
    {
        OLED_ShowChinese16(Line, Column + i, Fonts[i]);
    }
}
